describe('surface face colors', () => {
  it('matches the original literal implementation for real faces', () => {
    let zMin = Infinity, zMax = -Infinity;
    for (const z of vertices.z) {
      if (!Number.isFinite(z)) continue;
      zMin = Math.min(zMin, z); zMax = Math.max(zMax, z);
    }
    const zRange = Math.max(1, zMax - zMin);
    for (const face of vertices.faces) {
      const [a, b, c] = face as [number, number, number];
      const u = [vertices.x[b]! - vertices.x[a]!, vertices.y[b]! - vertices.y[a]!, vertices.z[b]! - vertices.z[a]!];
      const v = [vertices.x[c]! - vertices.x[a]!, vertices.y[c]! - vertices.y[a]!, vertices.z[c]! - vertices.z[a]!];
      const normal = [u[1]! * v[2]! - u[2]! * v[1]!, u[2]! * v[0]! - u[0]! * v[2]!, u[0]! * v[1]! - u[1]! * v[0]!];
      const length = Math.hypot(...normal);
      if (!Number.isFinite(length) || length === 0) { expect(surfaceFaceColor(vertices, a, b, c, zMin, zRange)).toBeNull(); continue; }
      const light = Math.abs((normal[0]! + 0.6 * normal[1]! + 0.8 * normal[2]!) / (length * Math.hypot(1, 0.6, 0.8)));
      const elevation = Math.min(1, Math.max(0, ((vertices.z[a]! + vertices.z[b]! + vertices.z[c]!) / 3 - zMin) / zRange));
      const relief = 0.58 + 0.62 * light;
      const low = [104, 126, 103];
      const high = [190, 177, 143];
      const channels = low.map((value, index) => Math.round((value + (high[index]! - value) * elevation) * relief));
      expect(surfaceFaceColor(vertices, a, b, c, zMin, zRange)).toBe(`rgb(${channels[0]}, ${channels[1]}, ${channels[2]})`);
    }
  });
});


it('reuses asynchronous raster work and evicts the oldest of four projections', async () => {
  const context = { save() {}, beginPath() {}, rect() {}, clip() {}, restore() {}, moveTo() {}, lineTo() {}, closePath() {}, fill() {}, fillRect() {}, fillStyle: '' };
  const blob = new Blob(['png']);
  const toBlob = vi.fn((callback: BlobCallback) => callback(blob));
  const element = document.createElement.bind(document);
  const create = vi.spyOn(document, 'createElement').mockImplementation(((name: string) => name === 'canvas' ? { getContext: () => context, toBlob } : element(name)) as typeof document.createElement);
  const createURL = vi.fn(() => `blob:${toBlob.mock.calls.length}`);
  const revoke = vi.fn();
  Object.defineProperty(URL, 'createObjectURL', { value: createURL, configurable: true });
  Object.defineProperty(URL, 'revokeObjectURL', { value: revoke, configurable: true });
  const mesh = { x: [0, 1, 0], y: [0, 0, 1], z: [0, 1, 2], faces: [[0, 1, 2]] } as Parameters<typeof createSurfaceRaster>[0];
  const projection = { width: 10, height: 10, xMin: 0, yMin: 0, xMax: 1, yMax: 1, scale: 1, left: 0, top: 0 };
  try {
    const first = createSurfaceRaster(mesh, projection);
    expect(createSurfaceRaster(mesh, { ...projection })).toBe(first);
    expect(await first).toBe('blob:1');
    for (let i = 1; i <= 4; i++) await createSurfaceRaster(mesh, { ...projection, left: i });
    expect(toBlob).toHaveBeenCalledTimes(5);
    expect(revoke).toHaveBeenCalledWith('blob:1');
  } finally { create.mockRestore(); }
});
